window.AUTH=window.AUTH||{};window.AUTH["23-250"]={"d":"23-250","id":"2023/23-250","n":"Becerra v. San Carlos Apache Tribe","briefs":[{"k":"petitioner","label":"Brief of petitioners Xavier Becerra, Secretary of Health and Human Services, et al.","date":"2024-01-04","url":"https://www.supremecourt.gov/DocketPDF/23/23-250/294968/20240104212631524_23-250tsUnitedStates.pdf","side":"pet","n":78},{"k":"respondent","label":"Brief of respondent San Carlos Apache Tribe (as to 23-250)","date":"2024-02-12","url":"https://www.supremecourt.gov/DocketPDF/23/23-250/300366/20240212130705181_File%20-%20SCA%20Merits%20Brief%20Final%20-%202-12-2024.pdf","side":"res","n":82},{"k":"respondent","label":"Brief of respondent Northern Arapaho Tribe (as to 23-253)","date":"2024-02-12","url":"https://www.supremecourt.gov/DocketPDF/23/23-250/300382/20240212140134697_23-253%20bs%20Brief%20for%20Respondent%20Northern%20Arapaho%20Tribe.pdf","side":"res","n":49},{"k":"reply","label":"Reply of petitioners Xavier Becerra, Secretary of Health and Human Services, et al.","date":"2024-03-13","url":"https://www.supremecourt.gov/DocketPDF/23/23-250/303026/20240313193617597_23-250rbUnitedStates.pdf","side":"pet","n":48}],"opinion":"https://www.supremecourt.gov/opinions/23pdf/602us1r30_g3bi.pdf","tr":true,"items":[{"t":"case","label":"Bowsher v. Merck & Co.","cite":"460 U.S. 824","y":1983,"id":"1982/81-1273","sc":1,"by":{"0":"26"}},{"t":"case","label":"Cherokee Nation of Okla. v. Leavitt","cite":"543 U.S. 631","y":2005,"id":"2004/02-1472","sc":1,"by":{"0":"6, 7","1":"9, 10, 12","2":"7","3":"3"},"q":[{"src":"brief","b":1,"text":"generally calculated by applying an ‘indirect cost rate’ to the amount of funds otherwise payable to the Tribe.","cite":"543 U.S. 631, 635"},{"src":"argument","who":"Mr. Unikowsky","text":"It took two cases from this Court, the Cherokee Nation case and then the Salazar versus Ramah Navajo Chapter case in 2012, for this Court to hold that the tribes actually are entitled to all of the contract support costs under the statute, and that's when these lawsuits started being brought."}]},{"t":"case","label":"Chickasaw Nation v. United States","cite":"534 U.S. 84","y":2001,"id":"2001/00-507","sc":1,"by":{"0":"47","3":"18"},"q":[{"src":"brief","b":0,"text":"produce an interpretation that * * * would conflict with the intent embodied in the statute Congress wrote,","cite":"534 U.S. 84, 94"},{"src":"argument","who":"Ms. Flynn","text":"It could, but it used the same buzzwords that come from this Court's articulation of that canon, which is \"liberally construed\" and \"ambiguities resolved to the benefit of the Indians.\" That comes from how this Court has phrased the canon in its cases like Chickasaw, Montana/Blackfeet."}]},{"t":"case","label":"Cook Inlet Tribal Council, Inc. v. Dotomain","cite":"10 F.4th 892","y":2021,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.4th/10/892/","by":{"0":"36","3":"8, 9"},"q":[{"src":"brief","b":0,"text":"merely divide[] into two the contract support costs already defined by § (a)(2).","cite":"10 F.4th 892, 895-896"},{"src":"brief","b":3,"text":"[a]n expense can be neither a direct contract support cost nor an indirect contract support cost [under § (a)(3)] if it is not, as defined by § (a)(2), a contract support cost.","cite":"10 F.4th 892, 896"}]},{"t":"case","label":"Dubin v. United States","cite":"599 U.S. 110","y":2023,"id":"2022/22-10","sc":1,"by":{"0":"39"},"q":[{"src":"brief","b":0,"text":"does not always turn solely on the broadest imaginable definitions of its component word[s].","cite":"599 U.S. 110, 120"}]},{"t":"case","label":"Fort McDermitt Paiute & Shoshone Tribe v. Becerra","cite":"6 F.4th 6","y":2021,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.4th/6/6/","by":{"0":"20, 24","3":"12"}},{"t":"case","label":"Luna Perez v. Sturgis Pub. Sch.","cite":"143 S. Ct. 859","y":2023,"url":"https://www.courtlistener.com/c/S.%20Ct./143/859/","sc":1,"by":{"0":"25"},"q":[{"src":"brief","b":0,"text":"is exactly how an ordinary reader would understand this [scheme].","cite":"143 S. Ct. 859, 864"}]},{"t":"case","label":"Menominee Indian Tribe of Wisconsin v. United States","cite":"577 U.S. 250","y":2016,"id":"2015/14-510","sc":1,"by":{"0":"3"}},{"t":"case","label":"Niz-Chavez v. Garland","cite":"141 S. Ct. 1474","y":2021,"id":"2020/19-863","sc":1,"by":{"0":"23"}},{"t":"case","label":"Oncale v. Sundowner Offshore Servs., Inc.","cite":"523 U.S. 75","y":1998,"id":"1997/96-568","sc":1,"by":{"0":"40","3":"15"},"q":[{"src":"brief","b":0,"text":"[S]tatutory prohibitions often go beyond the principal evil to cover reasonably comparable evils, and it is ultimately the provisions of our laws rather than the principal concerns of our legislators by which we are governed.","cite":"523 U.S. 75, 79"},{"src":"brief","b":3,"text":"statutory prohibitions often go beyond the principal evil to cover reasonably comparable evils, and it is ultimately the provisions of our laws rather than the principal concerns of our legislators by which we are governed.","cite":"523 U.S. 75, 79"}]},{"t":"case","label":"Oregon Dep’t of Fish & Wildlife v. Klamath Indian Tribe","cite":"473 U.S. 753","y":1985,"id":"1984/83-2148","sc":1,"by":{"0":"47","3":"17"},"q":[{"src":"brief","b":0,"text":"courts cannot ignore plain language that, viewed in historical context and given a ‘fair appraisal,’ clearly runs counter to a tribe’s later claims.","cite":"473 U.S. 753, 774"}]},{"t":"case","label":"Ramah Navajo Chapter v. Lujan","cite":"112 F.3d 1455","y":1997,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/112/1455/","by":{"0":"8, 40, 41","1":"13, 40","2":"10, 18, 46, 48","3":"15, 17"}},{"t":"case","label":"Republic of Argentina v. Weltover, Inc.","cite":"504 U.S. 607","y":1992,"id":"1991/91-763","sc":1,"by":{"0":"26, 41","3":"14"}},{"t":"case","label":"Robinson v. Shell Oil Co.","cite":"519 U.S. 337","y":1997,"id":"1996/95-1376","sc":1,"by":{"0":"46"},"q":[{"src":"brief","b":0,"text":"the specific context in which that language is used, and the broader context of the statute as a whole.","cite":"519 U.S. 337, 341"}]},{"t":"case","label":"Salazar v. Ramah Navajo Chapter","cite":"567 U.S. 182","y":2012,"id":"2011/11-551","sc":1,"by":{"0":"4, 45","1":"5, 8, 10, 12, 21, 36, 47, 48","2":"3, 7, 52, 55","3":"8, 17"},"q":[{"src":"brief","b":1,"text":"to render such services more responsive to the needs and desires of those communities.","cite":"567 U.S. 182, 185–86"},{"src":"brief","b":1,"text":"that th[e] secretarial amount failed to account for the full costs to tribes of providing services.","cite":"567 U.S. at 186"},{"src":"brief","b":2,"text":"failed to account for the full costs to tribes of providing services.","cite":"567 U.S. at 186"},{"src":"brief","b":2,"text":"do not share the [government’s] reading … is strong evidence that its reading is not, as it claims, ‘unambiguous[ly]’ correct.","cite":"567 U.S. at 197"},{"src":"argument","who":"Mr. Unikowsky","text":"That's the -- that's the -- I mean, that's assuming that the appropriations amount will stay the same, and that's completely speculative. I mean, after the Salazar --"},{"src":"argument","who":"Mr. Unikowsky","text":"It took two cases from this Court, the Cherokee Nation case and then the Salazar versus Ramah Navajo Chapter case in 2012, for this Court to hold that the tribes actually are entitled to all of the contract support costs under the statute, and that's when these lawsuits started being brought."},{"src":"argument","who":"Mr. Unikowsky","text":"Plus, tribes weren't -- I mean, again, like before 2012, tribes were getting much less than they were entitled to under the statute because of these appropriations caps which have been lifted by Congress after this Court's decision in Salazar versus Ramah Navajo Chapter."}]},{"t":"case","label":"South Carolina v. Catawba Indian Tribe, Inc.","cite":"476 U.S. 498","y":1986,"id":"1985/84-782","sc":1,"by":{"0":"10, 18, 47","3":"18"},"q":[{"src":"brief","b":0,"text":"does not permit reliance on ambiguities that do not exist.","cite":"476 U.S. 498, 506"},{"src":"brief","b":0,"text":"does not permit reliance on ambiguities that do not exist,","cite":"476 U.S. 498, 506"}]},{"t":"case","label":"Swinomish Indian Tribal Community v. Becerra","cite":"993 F.3d 917","y":2021,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/993/917/","by":{"0":"13, 19, 25, 38","2":"25","3":"10, 19"},"q":[{"src":"brief","b":0,"text":"text and structure do not require payment of contract support costs when a tribe spends money received from sources other than Indian Health Service, like insurance providers.","cite":"993 F.3d 917, 920"},{"src":"brief","b":0,"text":"just as [ISDA] speaks of contract support costs without any mention of insurance money, it elsewhere speaks of insurance money without any mention of contract support costs.","cite":"993 F.3d at 920"}]},{"t":"usc","label":"2 U.S.C. § 621","url":"https://www.law.cornell.edu/uscode/text/2/621","by":{"0":"45"}},{"t":"usc","label":"2 U.S.C. § 633","url":"https://www.law.cornell.edu/uscode/text/2/633","subs":["(b)"],"by":{"0":"45"}},{"t":"law","label":"Pub. L. No. 117-328","url":"https://www.govinfo.gov/link/plaw/117/public/328","by":{"0":"30"}},{"t":"law","label":"Pub. L. No. 95-563","url":"https://www.govinfo.gov/link/statute/92/2383","by":{"0":"11"}},{"t":"law","label":"Pub. L. No. 95-465","url":"https://www.govinfo.gov/link/statute/92/1296","by":{"0":"30"}},{"t":"law","label":"Pub. L. No. 102-154","url":"https://www.govinfo.gov/link/statute/105/1026","by":{"0":"30"}},{"t":"law","label":"Pub. L. No. 105-277","url":"https://www.govinfo.gov/link/plaw/105/public/277","by":{"0":"7","3":"16"}},{"t":"usc","label":"25 U.S.C. § 1601","url":"https://www.law.cornell.edu/uscode/text/25/1601","subs":["(1)"],"by":{"0":"3, 9","1":"1","2":"1, 4"}},{"t":"usc","label":"25 U.S.C. § 1602","url":"https://www.law.cornell.edu/uscode/text/25/1602","subs":["(7)"],"by":{"0":"9, 23","1":"32","2":"6, 39"},"q":[{"src":"brief","b":0,"text":"increas[ing] the proportion of all degrees in the health professions and allied and associated health professions awarded to Indians.","cite":"25 U.S.C. 1602"},{"src":"brief","b":2,"text":"to provide funding for programs and facilities operated by Indian tribes and tribal organizations in amounts that are not less than the amounts provided to programs and facilities operated directly by the Service.","cite":"25 U.S.C. § 1602(7)"}]},{"t":"usc","label":"25 U.S.C. § 1621e","url":"https://www.law.cornell.edu/uscode/text/25/1621e","subs":["(a)","(c)","(e)(3)(A)"],"by":{"0":"9, 23","1":"33, 7, 42","2":"5, 50, 50"}},{"t":"usc","label":"25 U.S.C. § 1621f","url":"https://www.law.cornell.edu/uscode/text/25/1621f","subs":["(a)","(a)(2)(D)","(a)(1)","(b)"],"by":{"0":"9, 34, 9, 34, 34","1":"33, 8, 34","2":"5, 21, 38","3":"10"}},{"t":"usc","label":"25 U.S.C. § 1641","url":"https://www.law.cornell.edu/uscode/text/25/1641","subs":["(d)(1)","(d)(2)","(a)","(c)(1)(B)","(d)","(d)(2)(A)","(c)(1)(A)"],"stext":{"head":"§1641. Treatment of payments under Social Security Act health benefits programs","paras":[[0,"(a) Disregard of Medicare, Medicaid, and CHIP payments in determining appropriations"],[0,"Any payments received by an Indian health program or by an urban Indian organization under title XVIII, XIX, or XXI of the Social Security Act [42 U.S.C. 1395 et seq., 1396 et seq., 1397aa et seq.] for services provided to Indians eligible for benefits under such respective titles shall not be considered in determining appropriations for the provision of health care and services to Indians."],[0,"(b) Nonpreferential treatment"],[0,"Nothing in this chapter authorizes the Secretary to provide services to an Indian with coverage under title XVIII, XIX, or XI 1 of the Social Security Act in preference to an Indian without such coverage."],[0,"(c) Use of funds"],[0,"(1) Special fund"],[0,"(A) 100 percent pass-through of payments due to facilities"],[2,"Notwithstanding any other provision of law, but subject to paragraph (2), payments to which a facility of the Service is entitled by reason of a provision of title XVIII or XIX of the Social Security Act [42 U.S.C. 1395 et seq., 1396 et seq.] shall be placed in a special fund to be held by the Secretary. In making payments from such fund, the Secretary shall ensure that each Service unit of the Service receives 100 percent of the amount to which the facilities of the Service, for which such Service unit makes collections, are entitled by reason of a provision of either such title."],[0,"(B) Use of funds"],[2,"Amounts received by a facility of the Service under subparagraph (A) by reason of a provision of title XVIII or XIX of the Social Security Act shall first be used (to such extent or in such amounts as are provided in appropriation Acts) for the purpose of making any improvements in the programs of the Service operated by or through such facility which may be necessary to achieve or maintain compliance with the applicable conditions and requirements of such respective title. Any amounts so received that are in excess of the amount necessary to achieve or maintain such conditions and requirements shall, subject to consultation with the Indian tribes being served by the Service unit, be used for reducing the health resource deficiencies (as determined in section 1621(c) of this title) of such Indian tribes, including the provision of services pursuant to section 1621d of this title."],[0,"(2) Direct payment option"],[1,"Paragraph (1) shall not apply to a tribal health program upon the election of such program under subsection (d) to receive payments directly. No payment may be made out of the special fund described in such paragraph with respect to reimbursement made for services provided by such program during the period of such election."],[0,"(d) Direct billing"],[0,"(1) In general"],[1,"Subject to complying with the requirements of paragraph (2), a tribal health program may elect to directly bill for, and receive payment for, health care items and services provided by such program for which payment is made under title XVIII, XIX, or XXI of the Social Security Act [42 U.S.C. 1395 et seq., 1396 et seq., 1397aa et seq.] or from any other third party payor."],[0,"(2) Direct reimbursement"],[0,"(A) Use of funds"],[2,"Each tribal health program making the election described in paragraph (1) with respect to a program under a title of the Social Security Act [42 U.S.C. 301 et seq.] shall be reimbursed directly by that program for items and services furnished without regard to subsection (c)(1), except that all amounts so reimbursed shall be used by the tribal health program for the purpose of making any improvements in facilities of the tribal health program that may be necessary to achieve or maintain compliance with the conditions and requirements applicable generally to such items and services under the program under such title and to provide additional health care services, improvements in health care facilities and tribal health programs, any health care-related purpose (including coverage for a service or service within a contract health service delivery area or any portion of a contract health service delivery area that would otherwise be provided as a contract health service), or otherwise to achieve the objectives provided in section 1602 of this title."],[0,"(B) Audits"],[2,"The amounts paid to a tribal health program making the election described in paragraph (1) with respect to a program under title XVIII, XIX, or XXI of the Social Security Act shall be subject to all auditing requirements applicable to the program under such title, as well as all auditing requirements applicable to programs administered by an Indian health program. Nothing in the preceding sentence shall be construed as limiting the application of auditing requirements applicable to amounts paid under title XVIII, XIX, or XXI of the Social Security Act."],[0,"(C) Identification of source of payments"],[2,"Any tribal health program that receives reimbursements or payments under title XVIII, XIX, or XXI of the Social Security Act shall provide to the Service a list of each provider enrollment number (or other identifier) under which such program receives such reimbursements or payments."],[0,"(3) Examination and implementation of changes"],[0,"(A) In general"],[2,"The Secretary, acting through the Service and with the assistance of the Administrator of the Centers for Medicare & Medicaid Services, shall examine on an ongoing basis and implement any administrative changes that may be necessary to facilitate direct billing and reimbursement under the program established under this subsection, including any agreements with States that may be necessary to provide for direct billing under a program under title XIX or XXI of the Social Security Act [42 U.S.C. 1396 et seq., 1397aa et seq.]."],[0,"(B) Coordination of information"],[2,"The Service shall provide the Administrator of the Centers for Medicare & Medicaid Services with copies of the lists submitted to the Service under paragraph (2)(C), enrollment data regarding patients served by the Service (and by tribal health programs, to the extent such data is available to the Service), and such other information as the Administrator may require for purposes of administering title XVIII, XIX, or XXI of the Social Security Act."],[0,"(4) Withdrawal from program"],[1,"A tribal health program that bills directly under the program established under this subsection may withdraw from participation in the same manner and under the same conditions that an Indian tribe or tribal organization may retrocede a contracted program to the Secretary under the authority of the Indian Self-Determination and Education Assistance Act (25 U.S.C. 450 et seq.).2 All cost accounting and billing authority under the program established under this subsection shall be returned to the Secretary upon the Secretary's acceptance of the withdrawal of participation in this program."],[0,"(5) Termination for failure to comply with requirements"],[1,"The Secretary may terminate the participation of a tribal health program or 3 in the direct billing program established under this subsection if the Secretary determines that the program has failed to comply with the requirements of paragraph (2). The Secretary shall provide a tribal health program with notice of a determination that the program has failed to comply with any such requirement and a reasonable opportunity to correct such noncompliance prior to terminating the program's participation in the direct billing program established under this subsection."],[0,"(e) Related provisions under the Social Security Act"],[0,"For provisions related to subsections (c) and (d), see sections 1880, 1911, and 2107(e)(1)(D) 2 of the Social Security Act [42 U.S.C. 1395qq, 1396j, 1397gg(e)(1)(D)]."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/25/1641?type=usc&year=mostrecent&link-type=html"},"by":{"0":"2, 2, 2","1":"34, 34, 7, 7, 34","2":"5, 5, 21, 26, 38, 6, 26, 43","3":"12, 10, 12, 7, 11"},"q":[{"src":"brief","b":0,"text":"or otherwise to achieve the objectives","cite":"25 U.S.C. 1641(d)(2)(A)"},{"src":"opinion","who":"Opinion of the Court (Chief Justice Roberts)","text":"shall not be considered in determining appropriations","cite":"25 U. S. C. § 1641(a)"}]},{"t":"usc","label":"25 U.S.C. § 1680c","url":"https://www.law.cornell.edu/uscode/text/25/1680c","subs":["(c)(1)(A)","(c)(1)(B)","(c)(2)"],"by":{"0":"2, 2, 2","1":"35","2":"43","3":"19, 19, 19"},"q":[{"src":"brief","b":0,"text":"that the provision of such health care services [to non-Indians] will not result in a denial or diminution of health services to eligible Indians.","cite":"25 U.S.C. 1680c(c)(1)(B)"}]},{"t":"usc","label":"25 U.S.C. § 5301","url":"https://www.law.cornell.edu/uscode/text/25/5301","subs":["(a)(1)"],"by":{"0":"2","1":"1, 4","2":"1"}},{"t":"usc","label":"25 U.S.C. § 450","url":"https://www.law.cornell.edu/uscode/text/25/450","by":{"0":"2"}},{"t":"usc","label":"25 U.S.C. § 5302","url":"https://www.law.cornell.edu/uscode/text/25/5302","subs":["(b)","(a)"],"by":{"0":"3","1":"4","2":"4"},"q":[{"src":"brief","b":2,"text":"a meaningful Indian self-determination policy which will permit an orderly transition from the Federal domination of programs for, and services to, Indians to effective and meaningful participation by the Indian people in the planning, conduct, and administration of those programs and services.","cite":"25 U.S.C. § 5302(b)"}]},{"t":"usc","label":"25 U.S.C. § 5304","url":"https://www.law.cornell.edu/uscode/text/25/5304","subs":["(c)","(f)"],"by":{"0":"3","2":"22, 20"}},{"t":"usc","label":"25 U.S.C. § 5321","url":"https://www.law.cornell.edu/uscode/text/25/5321","subs":["(g)","(a)(1)","(f)"],"stext":{"head":"§5321. Self-determination contracts","paras":[[0,"(a) Request by tribe; authorized programs"],[0,"(1) The Secretary is directed, upon the request of any Indian tribe by tribal resolution, to enter into a self-determination contract or contracts with a tribal organization to plan, conduct, and administer programs or portions thereof, including construction programs—"],[1,"(A) provided for in the Act of April 16, 1934 (48 Stat. 596), as amended [25 U.S.C. 5342 et seq.];"],[1,"(B) which the Secretary is authorized to administer for the benefit of Indians under the Act of November 2, 1921 (42 Stat. 208) [25 U.S.C. 13], and any Act subsequent thereto;"],[1,"(C) provided by the Secretary of Health and Human Services under the Act of August 5, 1954 (68 Stat. 674), as amended [42 U.S.C. 2001 et seq.];"],[1,"(D) administered by the Secretary for the benefit of Indians for which appropriations are made to agencies other than the Department of Health and Human Services or the Department of the Interior; and"],[1,"(E) for the benefit of Indians because of their status as Indians without regard to the agency or office of the Department of Health and Human Services or the Department of the Interior within which it is performed."],[0,"The programs, functions, services, or activities that are contracted under this paragraph shall include administrative functions of the Department of the Interior and the Department of Health and Human Services (whichever is applicable) that support the delivery of services to Indians, including those administrative activities supportive of, but not included as part of, the service delivery programs described in this paragraph that are otherwise contractable. The administrative functions referred to in the preceding sentence shall be contractable without regard to the organizational level within the Department that carries out such functions."],[0,"(2) If so authorized by an Indian tribe under paragraph (1) of this subsection, a tribal organization may submit a proposal for a self-determination contract, or a proposal to amend or renew a self-determination contract, to the Secretary for review. Subject to the provisions of paragraph (4), the Secretary shall, within ninety days after receipt of the proposal, approve the proposal and award the contract unless the Secretary provides written notification to the applicant that contains a specific finding that clearly demonstrates that, or that is supported by a controlling legal authority that—"],[1,"(A) the service to be rendered to the Indian beneficiaries of the particular program or function to be contracted will not be satisfactory;"],[1,"(B) adequate protection of trust resources is not assured;"],[1,"(C) the proposed project or function to be contracted for cannot be properly completed or maintained by the proposed contract;"],[1,"(D) the amount of funds proposed under the contract is in excess of the applicable funding level for the contract, as determined under section 5325(a) of this title; or"],[1,"(E) the program, function, service, or activity (or portion thereof) that is the subject of the proposal is beyond the scope of programs, functions, services, or activities covered under paragraph (1) because the proposal includes activities that cannot lawfully be carried out by the contractor."],[0,"Notwithstanding any other provision of law, the Secretary may extend or otherwise alter the 90-day period specified in the second sentence of this subsection,1 if before the expiration of such period, the Secretary obtains the voluntary and express written consent of the tribe or tribal organization to extend or otherwise alter such period. The contractor shall include in the proposal of the contractor the standards under which the tribal organization will operate the contracted program, service, function, or activity, including in the area of construction, provisions regarding the use of licensed and qualified architects, applicable health and safety standards, adherence to applicable Federal, State, local, or tribal building codes and engineering standards. The standards referred to in the preceding sentence shall ensure structural integrity, accountability of funds, adequate competition for subcontracting under tribal or other applicable law, the commencement, performance, and completion of the contract, adherence to project plans and specifications (including any applicable Federal construction guidelines and manuals), the use of proper materials and workmanship, necessary inspection and testing, and changes, modifications, stop work, and termination of the work when warranted."],[0,"(3) Upon the request of a tribal organization that operates two or more mature self-determination contracts, those contracts may be consolidated into one single contract."],[0,"(4) The Secretary shall approve any severable portion of a contract proposal that does not support a declination finding described in paragraph (2). If the Secretary determines under such paragraph that a contract proposal—"],[1,"(A) proposes in part to plan, conduct, or administer a program, function, service, or activity that is beyond the scope of programs covered under paragraph (1), or"],[1,"(B) proposes a level of funding that is in excess of the applicable level determined under section 5325(a) of this title,"],[0,"subject to any alteration in the scope of the proposal that the Secretary and the tribal organization agree to, the Secretary shall, as appropriate, approve such portion of the program, function, service, or activity as is authorized under paragraph (1) or approve a level of funding authorized under section 5325(a) of this title. If a tribal organization elects to carry out a severable portion of a contract proposal pursuant to this paragraph, subsection (b) of this section shall only apply to the portion of the contract that is declined by the Secretary pursuant to this subsection."],[0,"(b) Procedure upon refusal of request to contract"],[0,"Whenever the Secretary declines to enter into a self-determination contract or contracts pursuant to subsection (a) of this section, the Secretary shall—"],[1,"(1) state any objections in writing to the tribal organization,"],[1,"(2) provide assistance to the tribal organization to overcome the stated objections, and"],[1,"(3) provide the tribal organization with a hearing on the record with the right to engage in full discovery relevant to any issue raised in the matter and the opportunity for appeal on the objections raised, under such rules and regulations as the Secretary may promulgate, except that the tribe or tribal organization may, in lieu of filing such appeal, exercise the option to initiate an action in a Federal district court and proceed directly to such court pursuant to section 5331(a) of this title."],[0,"(c) Liability insurance; waiver of defense"],[0,"(1) Beginning in 1990, the Secretary shall be responsible for obtaining or providing liability insurance or equivalent coverage, on the most cost-effective basis, for Indian tribes, tribal organizations, and tribal contractors carrying out contracts, grant agreements and cooperative agreements pursuant to this chapter. In obtaining or providing such coverage, the Secretary shall take into consideration the extent to which liability under such contracts or agreements are covered by the Federal Tort Claims Act."],[0,"(2) In obtaining or providing such coverage, the Secretary shall, to the greatest extent practicable, give a preference to coverage underwritten by Indian-owned economic enterprises (as defined in section 1452 of this title), except that, for the purposes of this subsection, such enterprises may include non-profit corporations."],[0,"(3)(A) Any policy of insurance obtained or provided by the Secretary pursuant to this subsection shall contain a provision that the insurance carrier shall waive any right it may have to raise as a defense the sovereign immunity of an Indian tribe from suit, but that such waiver shall extend only to claims the amount and nature of which are within the coverage and limits of the policy and shall not authorize or empower such insurance carrier to waive or otherwise limit the tribe's sovereign immunity outside or beyond the coverage or limits of the policy of insurance."],[0,"(B) No waiver of the sovereign immunity of an Indian tribe pursuant to this paragraph shall include a waiver to the extent of any potential liability for interest prior to judgment or for punitive damages or for any other limitation on liability imposed by the law of the State in which the alleged injury occurs."],[0,"(d) Tribal organizations and Indian contractors deemed part of Public Health Service"],[0,"For purposes of section 233 of title 42, with respect to claims by any person, initially filed on or after December 22, 1987, whether or not such person is an Indian or Alaska Native or is served on a fee basis or under other circumstances as permitted by Federal law or regulations for personal injury, including death, resulting from the performance prior to, including, or after December 22, 1987, of medical, surgical, dental, or related functions, including the conduct of clinical studies or investigations, or for purposes of section 2679, title 28, with respect to claims by any such person, on or after November 29, 1990, for personal injury, including death, resulting from the operation of an emergency motor vehicle, an Indian tribe, a tribal organization or Indian contractor carrying out a contract, grant agreement, or cooperative agreement under sections 2 5321 or 5322 of this title is deemed to be part of the Public Health Service in the Department of Health and Human Services while carrying out any such contract or agreement and its employees (including those acting on behalf of the organization or contractor as provided in section 2671 of title 28 and including an individual who provides health care services pursuant to a personal services contract with a tribal organization for the provision of services in any facility owned, operated, or constructed under the jurisdiction of the Indian Health Service) are deemed employees of the Service while acting within the scope of their employment in carrying out the contract or agreement: Provided, That such employees shall be deemed to be acting within the scope of their employment in carrying out such contract or agreement when they are required, by reason of such employment, to perform medical, surgical, dental or related functions at a facility other than the facility operated pursuant to such contract or agreement, but only if such employees are not compensated for the performance of such functions by a person or entity other than such Indian tribe, tribal organization or Indian contractor."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/25/5321?type=usc&year=mostrecent&link-type=html"},"by":{"0":"3, 10","1":"24, 33, 10, 20, 46","2":"18, 53","3":"3"},"q":[{"src":"brief","b":0,"text":"be liberally construed for the benefit of the Indian Tribe participating in self-determination, and any ambiguity shall be resolved in favor of the Indian Tribe.","cite":"25 U.S.C. 5321(g)"},{"src":"brief","b":2,"text":"each provision of this chapter and each provision of a contract or funding agreement shall be liberally construed for the benefit of the Indian Tribe participating in self-determination, and any ambiguity shall be resolved in favor of the Indian Tribe.","cite":"25 U.S.C. § 5321(g)"}]},{"t":"usc","label":"25 U.S.C. § 5325","url":"https://www.law.cornell.edu/uscode/text/25/5325","subs":["(a)","(a)(1)","(a)(2)","(a)(2)(A)","(a)(2)(B)","(a)(3)","(a)(3)(A)","(a)(3)(A)(i)","(a)(3)(A)(ii)","(a)(3)(C)","(a)(4)","(a)(4)(A)","(e)","(k)(7)","(k)(8)","(k)(9)","(k)(11)","(m)","(m)(1)","(m)(2)","(a)(5)","(b)","(h)"],"stext":{"head":"§5325. Contract funding and indirect costs","paras":[[0,"(a) Amount of funds provided"],[0,"(1) The amount of funds provided under the terms of self-determination contracts entered into pursuant to this chapter shall not be less than the appropriate Secretary would have otherwise provided for the operation of the programs or portions thereof for the period covered by the contract, without regard to any organizational level within the Department of the Interior or the Department of Health and Human Services, as appropriate, at which the program, function, service, or activity or portion thereof, including supportive administrative functions that are otherwise contractable, is operated."],[0,"(2) There shall be added to the amount required by paragraph (1) contract support costs which shall consist of an amount for the reasonable costs for activities which must be carried on by a tribal organization as a contractor to ensure compliance with the terms of the contract and prudent management, but which—"],[1,"(A) normally are not carried on by the respective Secretary in his direct operation of the program; or"],[1,"(B) are provided by the Secretary in support of the contracted program from resources other than those under contract."],[0,"(3)(A) The contract support costs that are eligible costs for the purposes of receiving funding under this chapter shall include the costs of reimbursing each tribal contractor for reasonable and allowable costs of—"],[1,"(i) direct program expenses for the operation of the Federal program that is the subject of the contract; and"],[1,"(ii) any additional administrative or other expense incurred by the governing body of the Indian Tribe or Tribal organization and any overhead expense incurred by the tribal contractor in connection with the operation of the Federal program, function, service, or activity pursuant to the contract,"],[0,"except that such funding shall not duplicate any funding provided under subsection (a)(1) of this section."],[0,"(B) In calculating the reimbursement rate for expenses described in subparagraph (A)(ii), not less than 50 percent of the expenses described in subparagraph (A)(ii) that are incurred by the governing body of an Indian Tribe or Tribal organization relating to a Federal program, function, service, or activity carried out pursuant to the contract shall be considered to be reasonable and allowable."],[0,"(C) On an annual basis, during such period as a tribe or tribal organization operates a Federal program, function, service, or activity pursuant to a contract entered into under this chapter, the tribe or tribal organization shall have the option to negotiate with the Secretary the amount of funds that the tribe or tribal organization is entitled to receive under such contract pursuant to this paragraph."],[0,"(4) For each fiscal year during which a self-determination contract is in effect, any savings attributable to the operation of a Federal program, function, service, or activity under a self-determination contract by a tribe or tribal organization (including a cost reimbursement construction contract) shall—"],[1,"(A) be used to provide additional services or benefits under the contract; or"],[1,"(B) be expended by the tribe or tribal organization in the succeeding fiscal year, as provided in section 13a of this title."],[0,"(5) Subject to paragraph (6), during the initial year that a self-determination contract is in effect, the amount required to be paid under paragraph (2) shall include startup costs consisting of the reasonable costs that have been incurred or will be incurred on a one-time basis pursuant to the contract necessary—"],[1,"(A) to plan, prepare for, and assume operation of the program, function, service, or activity that is the subject of the contract; and"],[1,"(B) to ensure compliance with the terms of the contract and prudent management."],[0,"(6) Costs incurred before the initial year that a self-determination contract is in effect may not be included in the amount required to be paid under paragraph (2) if the Secretary does not receive a written notification of the nature and extent of the costs prior to the date on which such costs are incurred."],[0,"(b) Reductions and increases in amount of funds provided"],[0,"The amount of funds required by subsection (a) of this section—"],[1,"(1) shall not be reduced to make funding available for contract monitoring or administration by the Secretary;"],[1,"(2) shall not be reduced by the Secretary in subsequent years except pursuant to—"],[2,"(A) a reduction in appropriations from the previous fiscal year for the program or function to be contracted;"],[2,"(B) a directive in the statement of the managers accompanying a conference report on an appropriation bill or continuing resolution;"],[2,"(C) a tribal authorization;"],[2,"(D) a change in the amount of pass-through funds needed under a contract; or"],[2,"(E) completion of a contracted project, activity, or program;"],[1,"(3) shall not be reduced by the Secretary to pay for Federal functions, including, but not limited to, Federal pay costs, Federal employee retirement benefits, automated data processing, contract technical assistance or contract monitoring;"],[1,"(4) shall not be reduced by the Secretary to pay for the costs of Federal personnel displaced by a self-determination contract; and"],[1,"(5) may, at the request of the tribal organization, be increased by the Secretary if necessary to carry out this chapter or as provided in section 5324(c) of this title."],[0,"Notwithstanding any other provision in this chapter, the provision of funds under this chapter is subject to the availability of appropriations and the Secretary is not required to reduce funding for programs, projects, or activities serving a tribe to make funds available to another tribe or tribal organization under this chapter."],[0,"(c) Annual reports"],[0,"Not later than May 15 of each year, the Secretary shall prepare and submit to Congress an annual report on the implementation of this chapter. Such report shall include—"],[1,"(1) an accounting of the total amounts of funds provided for each program and the budget activity for direct program costs and contract support costs of tribal organizations under self-determination;"],[1,"(2) an accounting of any deficiency in funds needed to provide required contract support costs to all contractors for the fiscal year for which the report is being submitted;"],[1,"(3) the indirect cost rate and type of rate for each tribal organization that has been negotiated with the appropriate Secretary;"],[1,"(4) the direct cost base and type of base from which the indirect cost rate is determined for each tribal organization;"],[1,"(5) the indirect cost pool amounts and the types of costs included in the indirect cost pool; and"],[1,"(6) an accounting of any deficiency in funds needed to maintain the preexisting level of services to any Indian tribes affected by contracting activities under this chapter, and a statement of the amount of funds needed for transitional purposes to enable contractors to convert from a Federal fiscal year accounting cycle, as authorized by section 5324(d) of this title."],[0,"(d) Treatment of shortfalls in indirect cost recoveries"],[0,"(1) Where a tribal organization's allowable indirect cost recoveries are below the level of indirect costs that the tribal organizations should have received for any given year pursuant to its approved indirect cost rate, and such shortfall is the result of lack of full indirect cost funding by any Federal, State, or other agency, such shortfall in recoveries shall not form the basis for any theoretical over-recovery or other adverse adjustment to any future years' indirect cost rate or amount for such tribal organization, nor shall any agency seek to collect such shortfall from the tribal organization."],[0,"(2) Nothing in this subsection shall be construed to authorize the Secretary to fund less than the full amount of need for indirect costs associated with a self-determination contract."],[0,"(e) Liability for indebtedness incurred before fiscal year 1992"],[0,"Indian tribes and tribal organizations shall not be held liable for amounts of indebtedness attributable to theoretical or actual under-recoveries or theoretical over-recoveries of indirect costs, as defined in Office of Management and Budget Circular A–87, incurred for fiscal years prior to fiscal year 1992."],[0,"(f) Limitation on remedies relating to cost disallowances"],[0,"Any right of action or other remedy (other than those relating to a criminal offense) relating to any disallowance of costs shall be barred unless the Secretary has given notice of any such disallowance within three hundred and sixty-five days of receiving any required annual single agency audit report or, for any period covered by law or regulation in force prior to October 19, 1984, any other required final audit report. Such notice shall set forth the right of appeal and hearing to the board of contract appeals pursuant to section 5331 of this title. For the purpose of determining the 365-day period specified in this paragraph, an audit report shall be deemed to have been received on the date of actual receipt by the Secretary, if, within 60 days after receiving the report, the Secretary does not give notice of a determination by the Secretary to reject the single-agency report as insufficient due to noncompliance with chapter 75 of title 31 or noncompliance with any other applicable law. Nothing in this subsection shall be deemed to enlarge the rights of the Secretary with respect to section 5123 of this title."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/25/5325?type=usc&year=mostrecent&link-type=html"},"by":{"0":"39, 4, 5, 11, 15-17, 24, 25, 27, 36, 39, 4, 16, 20, 22, 24, 28, 4, 5, 12, 14-18, 21, 22, 24, 28, 30, 32-36, 40, 5, 21, 35, 36, 5, 21, 22, 35, 14, 15, 17, 22, 24, 27, 40, 6, 9, 15, 22, 35, 36, 6, 17, 18, 22, 32, 35-37, 6, 12, 17, 18, 22, 32, 35, 36, 38, 6, 24, 26, 33, 39, 26, 39, 39, 34, 26, 9, 23, 24, 33, 9, 23, 28, 33-35, 37, 39, 9, 11, 16, 23, 24","1":"3, 5, 33, 15, 18, 26, 27, 29, 27, 27, 3, 33, 10, 11, 26, 28, 22, 25, 2, 16, 17, 21, 22, 34, 12, 31, 36, 36, 23, 3, 11, 25, 2, 15, 16, 24, 25, 27, 34, 30, 34","2":"1, 6, 34, 1, 8, 17, 19-20, 30-34, 52, 55, 1, 9, 55, 9, 16-17, 19, 24-26, 30-32, 34, 36, 40, 52, 2, 20, 22-23, 28, 35, 54, 2, 20, 22, 28, 35, 54, 26, 27, 6, 19, 24, 36-37, 40, 2, 7, 15-16, 20-22, 24-29, 7, 29, 36-37, 54","3":"10, 13, 17, 2, 10, 2-4, 6-9, 21, 5, 3, 4, 8, 9, 7, 9, 13, 8, 9, 10, 12, 6, 21, 6, 2, 7, 11, 17, 5-7, 3, 11"},"q":[{"src":"brief","b":0,"text":"Secretary would have otherwise provided for the operation of the programs or portions thereof for the period covered by the contract.","cite":"25 U.S.C. 5325(a)(1)"},{"src":"brief","b":0,"text":"shall not be a basis for reducing the amount of funds otherwise obligated to the contract.","cite":"25 U.S.C. 5325(m)(1)"},{"src":"brief","b":2,"text":"incurred by the tribal contractor in connection with the operation of the Federal program, function, service, or activity pursuant to the contract.","cite":"25 U.S.C. § 5325(a)(3)(A)(i)"},{"src":"brief","b":2,"text":"once the Tribe establishes this infrastructure and collects third-party revenue, the [ISDA] requires the Tribe to deploy its program income ‘to further the general purposes of [its] contract’ with IHS.","cite":"25 U.S.C. § 5325(m)(1)"},{"src":"brief","b":3,"text":"carried on * * * as a contractor to ensure compliance with the terms of the contract.","cite":"25 U.S.C. 5325(a)(2)"},{"src":"brief","b":3,"text":"contract support costs * * * shall consist of.","cite":"25 U.S.C. 5325(a)(2)"}]},{"t":"usc","label":"25 U.S.C. § 5326","url":"https://www.law.cornell.edu/uscode/text/25/5326","stext":{"head":"§5326. Indian Health Service: availability of funds for Indian self-determination or self-governance contract or grant support costs","paras":[[0,"Before, on, and after October 21, 1998, and notwithstanding any other provision of law, funds available to the Indian Health Service in this Act or any other Act for Indian self-determination or self-governance contract or grant support costs may be expended only for costs directly attributable to contracts, grants and compacts pursuant to the Indian Self-Determination Act [25 U.S.C. 5321 et seq.] and no funds appropriated by this or any other Act shall be available for any contract support costs or indirect costs associated with any contract, grant, cooperative agreement, self-governance compact, or funding agreement entered into between an Indian tribe or tribal organization and any entity other than the Indian Health Service."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/25/5326?type=usc&year=mostrecent&link-type=html"},"by":{"0":"8, 11, 13-18, 25-27, 40-42, 46","1":"14, 17, 20, 36, 41","2":"10, 18, 45-49, 51-52","3":"13-15, 17"},"q":[{"src":"brief","b":0,"text":"associated with agreements with Medicare, Medicaid[,] and other third-party payers.","cite":"25 U.S.C. 5326"},{"src":"brief","b":0,"text":"notwithstanding any other provision of law.","cite":"25 U.S.C. 5326"},{"src":"brief","b":2,"text":"no funds appropriated by this or any other Act shall be available for any contract support costs or indirect costs associated with any contract, grant, cooperative agreement, self-governance compact, or funding agreement entered into between an Indian tribe or tribal organization and any entity other than the Indian Health Service.","cite":"25 U.S.C. § 5326"},{"src":"brief","b":2,"text":"may be expended only for costs directly attributable to contracts, grants and compacts pursuant to [ISDA] and no funds appropriated by this or any other Act shall be available for any contract support costs or indirect costs associated with any contract, grant, cooperative agreement, self-governance compact, or funding agreement entered into between an Indian tribe or tribal organization and any entity other than the Indian Health Service.","cite":"25 U.S.C. § 5326"},{"src":"brief","b":3,"text":"for any contract support costs or indirect costs associated with any contract, grant, cooperative agreement, self-governance compact, or funding agreement entered into between an Indian tribe or tribal organization and any entity other than [IHS].","cite":"25 U.S.C. 5326"},{"src":"brief","b":3,"text":"notwithstanding any other provision of law,","cite":"25 U.S.C. 5326"},{"src":"argument","who":"Mr. Unikowsky","text":"Section 5326 is no barrier for the tribes' recovery of costs in this case. The costs are directly attributable to the contract because they arise from the tribes' work pursuant to that contract, and they're not associated with any third-party Medicare or Medicaid provider agreements because the costs have nothing to do with the work under those agreements."}]},{"t":"usc","label":"25 U.S.C. § 5327","url":"https://www.law.cornell.edu/uscode/text/25/5327","by":{"0":"8"}},{"t":"usc","label":"25 U.S.C. § 5329","url":"https://www.law.cornell.edu/uscode/text/25/5329","subs":["(c)","(a)","(a)(1)"],"stext":{"head":"§5329. Contract or grant specifications","paras":[[0,"(a) Terms"],[0,"Each self-determination contract entered into under this chapter shall—"],[1,"(1) contain, or incorporate by reference, the provisions of the model agreement described in subsection (c) of this section (with modifications where indicated and the blanks appropriately filled in), and"],[1,"(2) subject to subsections (a) and (b) of section 5321 of this title, contain such other provisions as are agreed to by the parties."],[0,"(b) Payments; Federal records"],[0,"Notwithstanding any other provision of law, the Secretary may make payments pursuant to section 1(b)(6) of such model agreement. As provided in section 1(b)(7) of the model agreement, the records of the tribal government or tribal organization specified in such section shall not be considered Federal records for purposes of chapter 5 of title 5."],[0,"(c) Model agreement"],[0,"The model agreement referred to in subsection (a)(1) of this section reads as follows:"],[0,"\"SECTION 1. AGREEMENT BETWEEN THE SECRETARY AND THE ____________ TRIBAL GOVERNMENT."],[0,"\"(a) Authority and Purpose.—"],[1,"\"(1) Authority.—This agreement, denoted a Self-Determination Contract (referred to in this agreement as the 'Contract'), is entered into by the Secretary of the Interior or the Secretary of Health and Human Services (referred to in this agreement as the 'Secretary'), for and on behalf of the United States pursuant to title I of the Indian Self-Determination and Education Assistance Act (25 U.S.C. 450 et seq.) 1 and by the authority of the ____________ tribal government or tribal organization (referred to in this agreement as the 'Contractor'). The provisions of title I of the Indian Self-Determination and Education Assistance Act (25 U.S.C. 450 et seq.) 1 are incorporated in this agreement."],[1,"\"(2) Purpose.—Each provision of the Indian Self-Determination and Education Assistance Act (25 U.S.C. 450 et seq.) 1 and each provision of this Contract shall be liberally construed for the benefit of the Contractor to transfer the funding and the following related functions, services, activities, and programs (or portions thereof), that are otherwise contractable under section 102(a) of such Act, including all related administrative functions, from the Federal Government to the Contractor: (List functions, services, activities, and programs)."],[0,"\"(b) Terms, Provisions, and Conditions.—"],[1,"\"(1) Term.—Pursuant to section 105(c)(1) of the Indian Self-Determination and Education Assistance Act (25 U.S.C. 450j(c)(1)),1 the term of this contract shall be ____ years. Pursuant to section 105(d)(1) of such Act (25 U.S.C. 450j(d)) 1, upon the election by the Contractor, the period of this Contract shall be determined on the basis of a calendar year, unless the Secretary and the Contractor agree on a different period in the annual funding agreement incorporated by reference in subsection (f)(2)."],[1,"\"(2) Effective date.—This Contract shall become effective upon the date of the approval and execution by the Contractor and the Secretary, unless the Contractor and the Secretary agree on an effective date other than the date specified in this paragraph."],[1,"\"(3) Program standard.—The Contractor agrees to administer the program, services, functions and activities (or portions thereof) listed in subsection (a)(2) of the Contract in conformity with the following standards: (list standards)."],[1,"\"(4) Funding amount.—Subject to the availability of appropriations, the Secretary shall make available to the Contractor the total amount specified in the annual funding agreement incorporated by reference in subsection (f)(2). Such amount shall not be less than the applicable amount determined pursuant to section 106(a) of the Indian Self-Determination and Education Assistance Act (25 U.S.C. 450j–1).1"],[1,"\"(5) Limitation of costs.—The Contractor shall not be obligated to continue performance that requires an expenditure of funds in excess of the amount of funds awarded under this Contract. If, at any time, the Contractor has reason to believe that the total amount required for performance of this Contract or a specific activity conducted under this Contract would be greater than the amount of funds awarded under this Contract, the Contractor shall provide reasonable notice to the appropriate Secretary. If the appropriate Secretary does not take such action as may be necessary to increase the amount of funds awarded under this Contract, the Contractor may suspend performance of the Contract until such time as additional funds are awarded."],[1,"\"(6) Payment.—"],[2,"\"(A) In general.—Payments to the Contractor under this Contract shall—"],[3,"\"(i) be made as expeditiously as practicable; and"],[3,"\"(ii) include financial arrangements to cover funding during periods covered by joint resolutions adopted by Congress making continuing appropriations, to the extent permitted by such resolutions."],[2,"\"(B) Quarterly, semiannual, lump-sum, and other methods of payment.—"],[3,"\"(i) In general.—Pursuant to section 108(b) of the Indian Self-Determination and Education Assistance Act, and notwithstanding any other provision of law, for each fiscal year covered by this Contract, the Secretary shall make available to the Contractor the funds specified for the fiscal year under the annual funding agreement incorporated by reference pursuant to subsection (f)(2) by paying to the Contractor, on a quarterly basis, one-quarter of the total amount provided for in the annual funding agreement for that fiscal year, in a lump-sum payment or as semiannual payments, or any other method of payment authorized by law, in accordance with such method as may be requested by the Contractor and specified in the annual funding agreement."],[3,"\"(ii) Method of quarterly payment.—If quarterly payments are specified in the annual funding agreement incorporated by reference pursuant to subsection (f)(2), each quarterly payment made pursuant to clause (i) shall be made on the first day of each quarter of the fiscal year, except that in any case in which the Contract year coincides with the Federal fiscal year, payment for the first quarter shall be made not later than the date that is 10 calendar days after the date on which the Office of Management and Budget apportions the appropriations for the fiscal year for the programs, services, functions, and activities subject to this Contract."],[3,"\"(iii) Applicability.—Chapter 39 of title 31, United States Code, shall apply to the payment of funds due under this Contract and the annual funding agreement referred to in clause (i)."],[1,"\"(7) Records and monitoring.—"],[2,"\"(A) In general.—Except for previously provided copies of tribal records that the Secretary demonstrates are clearly required to be maintained as part of the recordkeeping system of the Department of the Interior or the Department of Health and Human Services (or both), records of the Contractor shall not be considered Federal records for purposes of chapter 5 of title 5, United States Code."],[2,"\"(B) Recordkeeping system.—The Contractor shall maintain a recordkeeping system and, upon reasonable advance request, provide reasonable access to such records to the Secretary."],[2,"\"(C) Responsibilities of contractor.—The Contractor shall be responsible for managing the day-to-day operations conducted under this Contract and for monitoring activities conducted under this Contract to ensure compliance with the Contract and applicable Federal requirements. With respect to the monitoring activities of the Secretary, the routine monitoring visits shall be limited to not more than two performance monitoring visits for this Contract by the head of each operating division, departmental bureau, or departmental agency, or duly authorized representative of such head unless—"],[3,"\"(i) the Contractor agrees to one or more additional visits; or"],[3,"\"(ii) the appropriate official determines that there is reasonable cause to believe that grounds for reassumption of the Contract, suspension of Contract payments, or other serious Contract performance deficiency may exist."],[2,"No additional visit referred to in clause (ii) shall be made until such time as reasonable advance notice that includes a description of the nature of the problem that requires the additional visit has been given to the Contractor."],[1,"\"(8) Property.—"],[2,"\"(A) In general.—As provided in section 105(f) of the Indian Self-Determination and Education Assistance Act (25 U.S.C. 450j(f)),1 at the request of the Contractor, the Secretary may make available, or transfer to the Contractor, all reasonably divisible real property, facilities, equipment, and personal property that the Secretary has used to provide or administer the programs, services, functions, and activities covered by this Contract. A mutually agreed upon list specifying the property, facilities, and equipment so furnished shall also be prepared by the Secretary, with the concurrence of the Contractor, and periodically revised by the Secretary, with the concurrence of the Contractor."],[2,"\"(B) Records.—The Contractor shall maintain a record of all property referred to in subparagraph (A) or other property acquired by the Contractor under section 105(f)(2)(A) of such Act for purposes of replacement."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/25/5329?type=usc&year=mostrecent&link-type=html"},"by":{"0":"10","1":"10, 10, 15, 10, 15, 23, 24, 46","2":"12, 3, 14, 23, 52, 35","3":"6, 10, 12"},"q":[{"src":"brief","b":2,"text":"The annual funding agreement under this Contract shall … contain … a brief description of the programs, services, functions, and activities to be performed (including those supported by financial resources other than those provided by the Secretary), to which the parties agree.","cite":"25 U.S.C. § 5329(c)"},{"src":"brief","b":2,"text":"Each provision of the [ISDA] and each provision of this Contract shall be liberally construed for the benefit of the Contractor.","cite":"25 U.S.C. § 5329(c)"},{"src":"brief","b":3,"text":"to transfer the funding and [a list of] related functions, services, activities, and programs,","cite":"25 U.S.C. 5329(c)"},{"src":"brief","b":3,"text":"a brief description of the programs, services, functions, and activities to be performed (including those supported by financial resources other than those provided by the Secretary).","cite":"25 U.S.C. 5329(c)"}]},{"t":"usc","label":"25 U.S.C. § 5331","url":"https://www.law.cornell.edu/uscode/text/25/5331","subs":["(a)"],"by":{"0":"10, 13"}},{"t":"usc","label":"25 U.S.C. § 5381","url":"https://www.law.cornell.edu/uscode/text/25/5381","by":{"0":"3"}},{"t":"usc","label":"25 U.S.C. § 5388","url":"https://www.law.cornell.edu/uscode/text/25/5388","subs":["(c)","(h)","(j)"],"stext":{"head":"§5388. Transfer of funds","paras":[[0,"(a) In general"],[0,"Pursuant to the terms of any compact or funding agreement entered into under this subchapter, the Secretary shall transfer to the Indian tribe all funds provided for in the funding agreement, pursuant to subsection (c) of this section, and provide funding for periods covered by joint resolution adopted by Congress making continuing appropriations, to the extent permitted by such resolutions. In any instance where a funding agreement requires an annual transfer of funding to be made at the beginning of a fiscal year, or requires semiannual or other periodic transfers of funding to be made commencing at the beginning of a fiscal year, the first such transfer shall be made not later than 10 days after the apportionment of such funds by the Office of Management and Budget to the Department, unless the funding agreement provides otherwise."],[0,"(b) Multiyear funding"],[0,"The Secretary is authorized to employ, upon tribal request, multiyear funding agreements. References in this subchapter to funding agreements shall include such multiyear funding agreements."],[0,"(c) Amount of funding"],[0,"The Secretary shall provide funds under a funding agreement under this subchapter in an amount equal to the amount that the Indian tribe would have been entitled to receive under self-determination contracts under this chapter, including amounts for direct program costs specified under section 5325(a)(1) of this title and amounts for contract support costs specified under section 5325(a)(2), (3), (5), and (6) of this title, including any funds that are specifically or functionally related to the provision by the Secretary of services and benefits to the Indian tribe or its members, all without regard to the organizational level within the Department where such functions are carried out."],[0,"(d) Prohibitions"],[0,"(1) In general"],[1,"Except as provided in paragraph (2), the Secretary is expressly prohibited from—"],[2,"(A) failing or refusing to transfer to an Indian tribe its full share of any central, headquarters, regional, area, or service unit office or other funds due under this chapter, except as required by Federal law;"],[2,"(B) withholding portions of such funds for transfer over a period of years; and"],[2,"(C) reducing the amount of funds required under this chapter—"],[3,"(i) to make funding available for self-governance monitoring or administration by the Secretary;"],[3,"(ii) in subsequent years, except pursuant to—"],[4,"(I) a reduction in appropriations from the previous fiscal year for the program or function to be included in a compact or funding agreement;"],[4,"(II) a congressional directive in legislation or accompanying report;"],[4,"(III) a tribal authorization;"],[4,"(IV) a change in the amount of pass-through funds subject to the terms of the funding agreement; or"],[4,"(V) completion of a project, activity, or program for which such funds were provided;"],[3,"(iii) to pay for Federal functions, including Federal pay costs, Federal employee retirement benefits, automated data processing, technical assistance, and monitoring of activities under this chapter; or"],[3,"(iv) to pay for costs of Federal personnel displaced by self-determination contracts under this chapter or self-governance;"],[0,"(2) Exception"],[1,"The funds described in paragraph (1)(C) may be increased by the Secretary if necessary to carry out this chapter or as provided in section 5324(c)(2) of this title."],[0,"(e) Other resources"],[0,"In the event an Indian tribe elects to carry out a compact or funding agreement with the use of Federal personnel, Federal supplies (including supplies available from Federal warehouse facilities), Federal supply sources (including lodging, airline transportation, and other means of transportation including the use of interagency motor pool vehicles) or other Federal resources (including supplies, services, and resources available to the Secretary under any procurement contracts in which the Department is eligible to participate), the Secretary shall acquire and transfer such personnel, supplies, or resources to the Indian tribe."],[0,"(f) Reimbursement to Indian Health Service"],[0,"With respect to functions transferred by the Indian Health Service to an Indian tribe, the Indian Health Service shall provide goods and services to the Indian tribe, on a reimbursable basis, including payment in advance with subsequent adjustment. The reimbursements received from those goods and services, along with the funds received from the Indian tribe pursuant to this subchapter, may be credited to the same or subsequent appropriation account which provided the funding, such amounts to remain available until expended."],[0,"(g) Prompt Payment Act"],[0,"Chapter 39 of title 31 shall apply to the transfer of funds due under a compact or funding agreement authorized under this subchapter."],[0,"(h) Interest or other income on transfers"],[0,"An Indian tribe is entitled to retain interest earned on any funds paid under a compact or funding agreement to carry out governmental or health purposes and such interest shall not diminish the amount of funds the Indian tribe is authorized to receive under its funding agreement in the year the interest is earned or in any subsequent fiscal year. Funds transferred under this subchapter shall be managed using the prudent investment standard."],[0,"(i) Carryover of funds"],[0,"All funds paid to an Indian tribe in accordance with a compact or funding agreement shall remain available until expended. In the event that an Indian tribe elects to carry over funding from 1 year to the next, such carryover shall not diminish the amount of funds the Indian tribe is authorized to receive under its funding agreement in that or any subsequent fiscal year."],[0,"(j) Program income"],[0,"All Medicare, Medicaid, or other program income earned by an Indian tribe shall be treated as supplemental funding to that negotiated in the funding agreement. The Indian tribe may retain all such income and expend such funds in the current year or in future years except to the extent that the Indian Health Care Improvement Act (25 U.S.C. 1601 et seq.) provides otherwise for Medicare and Medicaid receipts. Such funds shall not result in any offset or reduction in the amount of funds the Indian tribe is authorized to receive under its funding agreement in the year the program income is received or for any subsequent fiscal year."],[0,"(k) Limitation of costs"],[0,"An Indian tribe shall not be obligated to continue performance that requires an expenditure of funds in excess of the amount of funds transferred under a compact or funding agreement. If at any time the Indian tribe has reason to believe that the total amount provided for a specific activity in the compact or funding agreement is insufficient the Indian tribe shall provide reasonable notice of such insufficiency to the Secretary. If the Secretary does not increase the amount of funds transferred under the funding agreement, the Indian tribe may suspend performance of the activity until such time as additional funds are transferred."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/25/5388?type=usc&year=mostrecent&link-type=html"},"by":{"0":"24, 25, 34, 9, 10, 14, 16, 24","1":"29, 32","2":"36","3":"3, 4, 17"},"q":[{"src":"brief","b":0,"text":"shall be treated as supplemental funding to that negotiated in the funding agreement","cite":"25 U.S.C. 5388(j)"},{"src":"brief","b":0,"text":"[s]uch funds shall not result in any offset or reduction in the * * * funding agreement.","cite":"25 U.S.C. 5388(j)"},{"src":"brief","b":3,"text":"All Medicare, Medicaid, or other program income earned by an Indian tribe shall be treated as supplemental funding to that negotiated in the funding agreement.","cite":"25 U.S.C. 5388"}]},{"t":"usc","label":"25 U.S.C. § 5396","url":"https://www.law.cornell.edu/uscode/text/25/5396","subs":["(a)"],"by":{"0":"24"}},{"t":"law","label":"Pub. L. No. 100-472","url":"https://www.govinfo.gov/link/statute/102/2292","by":{"0":"4"}},{"t":"law","label":"Pub. L. No. 103-413","url":"https://www.govinfo.gov/link/statute/108/4257","by":{"0":"5"}},{"t":"usc","label":"25 U.S.C. § 13","url":"https://www.law.cornell.edu/uscode/text/25/13","by":{"0":"3"}},{"t":"usc","label":"42 U.S.C. § 1395qq","url":"https://www.law.cornell.edu/uscode/text/42/1395qq","subs":["(a)"],"by":{"0":"9, 23","2":"5, 6, 21"}},{"t":"usc","label":"42 U.S.C. § 1396j","url":"https://www.law.cornell.edu/uscode/text/42/1396j","subs":["(a)"],"by":{"0":"9, 23","2":"5, 6, 21"}},{"t":"reg","label":"25 C.F.R. § 900.114","url":"https://www.ecfr.gov/current/title-25/section-900.114","by":{"0":"33"}},{"t":"case","label":"Bloate v. United States","cite":"559 U.S. 196","y":2010,"id":"2009/08-728","sc":1,"by":{"1":"24"}},{"t":"case","label":"Burrage v. United States","cite":"571 U.S. 204","y":2014,"id":"2013/12-7515","sc":1,"by":{"1":"37"}},{"t":"case","label":"Christopher v. SmithKline Beecham Corp.","cite":"567 U.S. 142","y":2012,"id":"2011/11-204","sc":1,"by":{"1":"21"}},{"t":"case","label":"Cnty. of Yakima v. Confederated Tribes & Bands of Yakima Indian Nation","cite":"502 U.S. 251","y":1992,"id":"1991/90-408","sc":1,"by":{"1":"45","2":"51"},"q":[{"src":"brief","b":2,"text":"[s]tatutes are to be construed liberally in favor of the Indians, with ambiguous provisions interpreted to their benefit.’","cite":"502 U.S. 251, 269"}]},{"t":"case","label":"FERC v. Elec. Power Supply Ass’n","cite":"577 U.S. 260","y":2016,"id":"2015/14-840","sc":1,"by":{"1":"45"},"q":[{"src":"brief","b":1,"text":"a non-hyperliteral reading is needed to prevent the statute from assuming near-infinite breadth.","cite":"577 U.S. 260, 278"}]},{"t":"case","label":"Gustafson v. Alloyd Co.","cite":"513 U.S. 561","y":1995,"id":"1994/93-404","sc":1,"by":{"1":"43"},"q":[{"src":"brief","b":1,"text":"to avoid ascribing to one word a meaning so broad that it is inconsistent with its accompanying words, thus giving ‘unintended breadth to the Acts of Congress.’","cite":"513 U.S. 561, 575"}]},{"t":"case","label":"HollyFrontier Cheyenne Refin., LLC v. Renewable Fuels Ass’n","cite":"141 S. Ct. 2172","y":2021,"id":"2020/20-472","sc":1,"by":{"1":"28"}},{"t":"case","label":"Jamestown S’Klallam Tribe v. Azar","cite":"486 F. Supp. 3d 83","y":2020,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/486/83/","by":{"1":"35","3":"20"},"q":[{"src":"brief","b":1,"text":"not part of the IHS Programs transferred to the Tribe.","cite":"486 F. Supp. 3d 83, 88"},{"src":"argument","who":"Mr. Miller","text":"That issue has been litigated, and the Court have held in the Jamestown case that there's a reasonableness limitation to the leasing costs."}]},{"t":"case","label":"McGirt v. Oklahoma","cite":"140 S. Ct. 2452","y":2020,"id":"2019/18-9526","sc":1,"by":{"1":"47"}},{"t":"case","label":"Michigan v. Bay Mills Indian Cmty.","cite":"572 U.S. 782","y":2014,"id":"2013/12-515","sc":1,"by":{"1":"47"}},{"t":"case","label":"Mont v. United States","cite":"139 S. Ct. 1826","y":2019,"id":"2018/17-8995","sc":1,"by":{"1":"22"},"q":[{"src":"brief","b":1,"text":"has often recognized … can bear a ‘broad interpretation.’","cite":"139 S. Ct. 1826, 1832"}]},{"t":"case","label":"Okla. Tax Comm’n v. Citizen Band of Potawatomi Indian Tribe of Okla.","cite":"498 U.S. 505","y":1991,"id":"1990/89-1322","sc":1,"by":{"1":"47"}},{"t":"case","label":"Sandoz Inc. v. Amgen Inc.","cite":"582 U.S. 1","y":2017,"id":"2016/15-1039","sc":1,"by":{"1":"36"},"q":[{"src":"brief","b":1,"text":"arguments [cannot] overcome the statute’s plain language, which is [the] ‘primary guide’ to Congress’ preferred policy,","cite":"582 U.S. 1, 21"}]},{"t":"case","label":"Sosa v. Alvarez-Machain","cite":"542 U.S. 692","y":2004,"id":"2003/03-339","sc":1,"by":{"1":"22"}},{"t":"case","label":"United States v. Gonzales","cite":"520 U.S. 1","y":1997,"id":"1996/95-1605","sc":1,"by":{"1":"21"},"q":[{"src":"brief","b":1,"text":"[T]he word ‘any’ has an expansive meaning, that is, ‘one or some indiscriminately of whatever kind.’","cite":"520 U.S. 1, 5"}]},{"t":"case","label":"United States v. Jicarilla Apache Nation","cite":"564 U.S. 162","y":2011,"id":"2010/10-382","sc":1,"by":{"1":"42"}},{"t":"case","label":"United States v. Lara","cite":"541 U.S. 193","y":2004,"id":"2003/03-107","sc":1,"by":{"1":"45"}},{"t":"case","label":"Wooden v. United States","cite":"595 U.S. 360","y":2022,"id":"2021/20-5279","sc":1,"by":{"1":"40"}},{"t":"case","label":"Yates v. United States","cite":"574 U.S. 528","y":2015,"id":"2014/13-7451","sc":1,"by":{"1":"4"}},{"t":"case","label":"Ysleta del Sur Pueblo v. Texas","cite":"596 U.S. 685","y":2022,"id":"2021/20-493","sc":1,"by":{"1":"20, 45, 47"}},{"t":"usc","label":"25 U.S.C. § 1616a","url":"https://www.law.cornell.edu/uscode/text/25/1616a","subs":["(k)(1)"],"by":{"1":"32"}},{"t":"usc","label":"25 U.S.C. § 1616c","url":"https://www.law.cornell.edu/uscode/text/25/1616c","subs":["(b)(2)"],"by":{"1":"33"}},{"t":"usc","label":"25 U.S.C. § 1616q","url":"https://www.law.cornell.edu/uscode/text/25/1616q","by":{"1":"33"}},{"t":"usc","label":"25 U.S.C. § 1621","url":"https://www.law.cornell.edu/uscode/text/25/1621","subs":["(e)"],"by":{"1":"33"}},{"t":"usc","label":"25 U.S.C. § 1623","url":"https://www.law.cornell.edu/uscode/text/25/1623","subs":["(b)"],"by":{"1":"6, 8, 24","2":"6, 13, 21"}},{"t":"usc","label":"25 U.S.C. § 1631","url":"https://www.law.cornell.edu/uscode/text/25/1631","subs":["(c)(1)(C)"],"by":{"1":"8, 33"}},{"t":"usc","label":"25 U.S.C. § 1645","url":"https://www.law.cornell.edu/uscode/text/25/1645","subs":["(c)"],"by":{"1":"7, 33"}},{"t":"usc","label":"25 U.S.C. § 1680a","url":"https://www.law.cornell.edu/uscode/text/25/1680a","by":{"1":"33"}},{"t":"usc","label":"25 U.S.C. § 5361","url":"https://www.law.cornell.edu/uscode/text/25/5361","subs":["(8)"],"by":{"1":"24"}},{"t":"usc","label":"42 U.S.C. § 254b","url":"https://www.law.cornell.edu/uscode/text/42/254b","by":{"1":"39"}},{"t":"law","label":"Pub. L. No. 93-638","url":"https://www.govinfo.gov/link/statute/88/2203","by":{"1":"4, 5"}},{"t":"law","label":"Pub. L. No. 94-437","url":"https://www.govinfo.gov/link/statute/90/1400","by":{"1":"6"}},{"t":"law","label":"Pub. L. No. 100-713","url":"https://www.govinfo.gov/link/statute/102/4784","by":{"1":"6, 7"}},{"t":"law","label":"Pub. L. No. 102-573","url":"https://www.govinfo.gov/link/statute/106/4526","by":{"1":"7"}},{"t":"law","label":"Pub. L. No. 106-417","url":"https://www.govinfo.gov/link/plaw/106/public/417","by":{"1":"7"}},{"t":"case","label":"Bradley v. School Board of City of Richmond","cite":"416 U.S. 696","y":1974,"id":"1973/72-1322","sc":1,"by":{"2":"53"}},{"t":"case","label":"Landgraf v. USI Film Products","cite":"511 U.S. 244","y":1994,"id":"1993/92-757","sc":1,"by":{"2":"53"}},{"t":"case","label":"Maine Community Health Options v. United States","cite":"140 S. Ct. 1308","y":2020,"id":"2019/18-1023","sc":1,"by":{"2":"30"}},{"t":"case","label":"Minnesota v. Mille Lacs Band of Chippewa Indians","cite":"526 U.S. 172","y":1999,"id":"1998/97-1337","sc":1,"by":{"2":"51"},"q":[{"src":"brief","b":2,"text":"Indian treaties are to be interpreted liberally in favor of the Indians, and … any ambiguities are to be resolved in their favor.","cite":"526 U.S. 172, 200"}]},{"t":"case","label":"Yellen v. Confederated Tribes of Chehalis Reservation","cite":"141 S. Ct. 2434","y":2021,"id":"2020/20-543","sc":1,"by":{"2":"4"},"q":[{"src":"brief","b":2,"text":"deliver[] federally funded economic, infrastructure, health, or education benefits to the tribe’s membership.","cite":"141 S. Ct. 2434, 2439"}]},{"t":"usc","label":"28 U.S.C. § 1442","url":"https://www.law.cornell.edu/uscode/text/28/1442","subs":["(d)(5)"],"by":{"2":"31"},"q":[{"src":"brief","b":2,"text":"[t]he term ‘State’ includes the District of Columbia,","cite":"28 U.S.C. § 1442(d)(5)"}]},{"t":"usc","label":"38 U.S.C. § 1984","url":"https://www.law.cornell.edu/uscode/text/38/1984","subs":["(i)"],"by":{"2":"47"}},{"t":"usc","label":"41 U.S.C. § 7101","url":"https://www.law.cornell.edu/uscode/text/41/7101","by":{"2":"14"}},{"t":"law","label":"PROGRESS for Indian Tribes Act, Pub. L. No. 116-180","url":"https://www.govinfo.gov/link/plaw/116/public/180","by":{"2":"9"}},{"t":"reg","label":"2 C.F.R. pt. 200","url":"https://www.ecfr.gov/current/title-2/part-200","by":{"2":"44","3":"21"}},{"t":"case","label":"Biden v. Nebraska","cite":"600 U.S. 477","y":2023,"id":"2022/22-506","sc":1,"by":{"3":"18, 19"}},{"t":"case","label":"Boechler, P.C. v. Commissioner","cite":"596 U.S. 199","y":2022,"id":"2021/20-1472","sc":1,"by":{"3":"18"}},{"t":"case","label":"Department of Agric. Rural Dev. Rural Hous. Serv. v. Kirtz","cite":"144 S. Ct. 457","y":2024,"id":"2023/22-846","sc":1,"by":{"3":"16"}},{"t":"case","label":"DePierre v. United States","cite":"564 U.S. 70","y":2011,"id":"2010/09-1533","sc":1,"by":{"3":"15"}},{"t":"case","label":"(I) Cases—Continued: Lac du Flambeau Band of Lake Superior Chippewa Indians v. Coughlin","cite":"599 U.S. 382","y":2023,"id":"2022/22-227","sc":1,"by":{"3":"18"}},{"t":"case","label":"Maracich v. Spears","cite":"570 U.S. 48","y":2013,"id":"2012/12-25","sc":1,"by":{"3":"13"},"q":[{"src":"brief","b":3,"text":"phrase ‘in connection with’ is essentially ‘indeterminat[e]’ because connections, like relations, ‘stop nowhere.’","cite":"570 U.S. 48, 59"}]},{"t":"case","label":"Shady Grove Orthopedic Assocs., P.A. v. Allstate Ins. Co.","cite":"559 U.S. 393","y":2010,"id":"2009/08-1008","sc":1,"by":{"3":"15"}},{"t":"usc","label":"25 U.S.C. § 5235","url":"https://www.law.cornell.edu/uscode/text/25/5235","subs":["(a)(2)(B)"],"by":{"3":"5"}}]};